gned' : '' ?></small></span></label><?php endforeach; ?><?php if (!$eligibleStudents): ?><div class="revision-empty">No active enrolled students are available.</div><?php endif; ?></div><div class="revision-actions mt-3"><button type="button" class="btn btn-outline-secondary btn-sm" data-select-eligible>Select all visible</button><button class="btn btn-primary" type="submit">Assign selected students</button></div></form></section><?php endif; ?>
