<div class="modal fade" id="revision-create-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog"><div class="modal-content"><form method="post" action="<?= $escape($base . '/admin/requests/revision-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_admin_csrf_token()) ?>"><input type="hidden" name="action" value="create_template"><div class="modal-header"><h2 class="modal-title h5">New Revision Plan</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><label class="revision-field mb-3"><span>Course</span><select class="form-select" name="course_id" required><?php foreach ($courses as $course): ?><option value="<?= $escape($course['course_id']) ?>" <?= $selectedCourse === (string) $course['course_id'] ? 'selected' : '' ?>><?= $escape($course['course_title']) ?></option><?php endforeach; ?></select></label><label class="revision-field mb-3"><span>Plan name</span><input class="form-control" name="title" maxlength="180" required placeholder="Algebra Revision"></label><label class="revision-field"><span>Description <small class="revision-help">Optional</small></span><textarea class="form-control" name="description" rows="3" maxlength="1000"></textarea></label></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Create Plan</button></div></form></div></div></div>
<div class="modal fade" id="revision-add-days-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-sm"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5">Add days</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p class="revision-help">Add consecutive days to this plan.</p><div class="revision-actions mb-3"><button type="button" class="btn btn-outline-secondary btn-sm" data-quick-days="1">+1 Day</button><button type="button" class="btn btn-outline-secondary btn-sm" data-quick-days="3">+3 Days</button><button type="button" class="btn btn-outline-secondary btn-sm" data-quick-days="7">+7 Days</button></div><label class="revision-field"><span>Custom number (1–30)</span><input class="form-control" type="number" min="1" max="30" value="7" data-custom-days></label></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-primary" data-confirm-add-days>Add Days</button></div></div></div></div>
<div class="modal fade" id="revision-publish-assign-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form method="post" action="<?= $escape($base . '/admin/requests/revision-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_admin_csrf_token()) ?>"><input type="hidden" name="action" value="publish_and_assign"><input type="hidden" name="template_id" value="<?= (int) $templateId ?>"><input type="hidden" name="version_id" value="<?= (int) $versionId ?>"><input type="hidden" name="structure_json" value=""><input type="hidden" name="title" value=""><input type="hidden" name="description" value=""><div class="modal-header"><div><h2 class="modal-title h5">Publish &amp; Assign</h2><p class="revision-help mb-0" data-publish-assign-summary>Choose students and a start date.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><label class="revision-field mb-3"><span>Start date</span><input class="form-control" type="date" name="start_date" value="<?= date('Y-m-d') ?>" required></label><label class="revision-field mb-3"><span>Search enrolled students</span><input class="form-control" type="search" placeholder="Name or email" data-student-filter-modal></label><div class="revision-student-list" data-student-list-modal><?php foreach ($eligibleStudents as $student): ?><label class="revision-student-row" data-student-row-modal data-student-text-modal="<?= $escape(strtolower(($student['full_name'] ?? '') . ' ' . ($student['username'] ?? ''))) ?>"><input type="checkbox" name="student_ids[]" value="<?= (int) $student['user_id'] ?>"><span><strong><?= $escape($student['full_name'] ?: $student['username']) ?></strong><small><?= $escape($student['username']) ?></small></span></label><?php endforeach; ?><?php if (!$eligibleStudents): ?><div class="revision-empty">No active enrolled students are available.</div><?php endif; ?></div><div class="revision-actions mt-3"><button type="button" class="btn btn-outline-secondary btn-sm" data-select-eligible-modal>Select all visible</button><span class="revision-help" data-selected-modal>Selected: 0</span></div><label class="revision-field mt-3"><span><input type="checkbox" name="allow_work_ahead" value="1"> Allow students to work ahead</span><small class="revision-help">Optional. Future days stay locked when this is off.</small></label></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" type="submit">Publish &amp; Assign</button></div></form></div></div></div>
<div class="modal fade" id="revision-add-batch-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-sm"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5">Add Batch</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p class="revision-help mb-3">Create a group of days now and add its content when ready.</p><label class="revision-field mb-3"><span>Batch name</span><input class="form-control" type="text" value="New Batch" data-new-batch-title maxlength="180"></label><label class="revision-field mb-3"><span>Number of Days (0–30)</span><input class="form-control" type="number" min="0" max="30" value="1" data-new-batch-days></label><label class="revision-field"><span>Description <small class="revision-help">Optional</small></span><textarea class="form-control" rows="2" maxlength="1000" data-new-batch-description></textarea></label></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-primary" data-confirm-add-batch>Add Batch</button></div></div></div></div>
<div class="modal fade" id="revision-delete-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog"><div class="modal-content"><form method="post" action="<?= $escape($base . '/admin/requests/revision-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_admin_csrf_token()) ?>"><input type="hidden" name="action" value="delete_template"><input type="hidden" name="template_id" value="" data-delete-template-id><div class="modal-header"><h2 class="modal-title h5">Delete Revision Plan?</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p class="mb-2"><strong data-delete-template-title>Revision Plan</strong></p><p class="revision-help mb-0" data-delete-normal-warning>This plan and its Revision Plan data will be permanently deleted.</p><div data-delete-activity-warning hidden><p class="text-danger mb-2">This plan has student activity.</p><p class="revision-help">Deleting it will also remove its Revision Plan assignments and progress for students.</p><label class="revision-field mt-3"><span>Type <strong>DELETE</strong> to continue</span><input class="form-control" name="delete_confirmation" type="text" autocomplete="off" data-delete-confirmation></label></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" type="submit" data-delete-submit>Delete Plan</button></div></form></div></div></div>
<script>
(function(){
'use strict';
var state = <?= json_encode($structure, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
var batchIds = <?= json_encode(array_values(array_map(static fn(array $batch): int => (int) ($batch['id'] ?? 0), (array) ($selectedVersion['batches'] ?? []))), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
var items = <?= json_encode($itemOptions, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
var resources = <?= json_encode($resourceOptions, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
var readOnly = <?= $selectedVersion && $selectedVersion['status'] !== 'draft' ? 'true' : 'false' ?>;
var root = document.querySelector('[data-hierarchy]');
document.addEventListener('click',function(e){var addBatch=e.target.closest('[data-add-batch]');if(!addBatch||readOnly)return;e.stopImmediatePropagation();var modal=document.getElementById('revision-add-batch-modal');if(window.bootstrap&&modal)bootstrap.Modal.getOrCreateInstance(modal).show();},true);
document.addEventListener('click',function(e){var confirmBatch=e.target.closest('[data-confirm-add-batch]');if(!confirmBatch||readOnly)return;e.stopImmediatePropagation();var title=(document.querySelector('[data-new-batch-title]')?.value||'New Batch').trim()||'New Batch';var description=(document.querySelector('[data-new-batch-description]')?.value||'').trim();var count=Math.max(0,Math.min(30,parseInt(document.querySelector('[data-new-batch-days]')?.value||'0',10)||0));state=readState();var b=batch();b.title=title;b.description=description;for(var i=0;i<count;i++)b.days.push(day());state.batches.push(b);render();var modal=document.getElementById('revision-add-batch-modal');if(window.bootstrap&&modal)bootstrap.Modal.getOrCreateInstance(modal).hide();},true);
var esc = function(v){return String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');};
function req(){return {title:'',description:'',requirement_type:'checklist',is_required:1,sort_order:0,linked_course_item_id:'',allow_multiple_files:0,accepted_file_policy:'pdf',resource_ids:[]};}
function day(){return {day_number:1,title:'Day 1',description:'',sort_order:0,requirements:[],activity_groups:[]};}
function batch(){return {title:'New Batch',description:'',suggested_days:0,sort_order:0,days:[]};}
function options(current,type){if(type==='course_item'){return '<option value="">Choose a Course Item</option>'+items.map(function(i){return '<option value="'+esc(i.id)+'" '+(String(current||'')===String(i.id)?'selected':'')+'>'+esc(i.title+' · '+i.section)+'</option>';}).join('');}return '';}
function resourceOptions(selected){selected=(selected||[]).map(String);return resources.map(function(r){return '<option value="'+r.id+'" '+(selected.indexOf(String(r.id))>=0?'selected':'')+'>'+esc(r.name)+'</option>';}).join('');}
function requirementHtml(r, key){var disabled=readOnly?'disabled':'';return '<article class="revision-requirement" data-requirement="'+key+'"><label class="revision-field"><span>Requirement title</span><input data-field="title" value="'+esc(r.title)+'" '+disabled+'></label><label class="revision-field"><span>Type</span><select data-field="requirement_type" '+disabled+'><option value="checklist" '+(r.requirement_type==='checklist'?'selected':'')+'>Checklist</option><option value="resource" '+(r.requirement_type==='resource'?'selected':'')+'>Resource</option><option value="course_item" '+(r.requirement_type==='course_item'?'selected':'')+'>Course Item</option><option value="upload" '+(r.requirement_type==='upload'?'selected':'')+'>Upload evidence</option></select></label><label class="revision-field full"><span>Instructions</span><textarea data-field="description" rows="2" '+disabled+'>'+esc(r.description)+'</textarea></label><label class="revision-field" data-requirement-config="course_item"><span>Search Course Items</span><input type="search" placeholder="Lecture, recording, homework..." data-course-item-filter '+disabled+'><select data-field="linked_course_item_id" '+disabled+'>'+options(r.linked_course_item_id,r.requirement_type)+'</select></label><label class="revision-field" data-requirement-config="resource"><span>Shared materials</span><select data-field="resource_ids" multiple '+disabled+'>'+resourceOptions(r.resource_ids)+'</select></label><label class="revision-field" data-requirement-config="upload"><span>Accepted upload policy</span><input data-field="accepted_file_policy" value="'+esc(r.accepted_file_policy||'pdf')+'" '+disabled+'></label><label class="revision-field" data-requirement-config="upload"><span><input type="checkbox" data-field="allow_multiple_files" '+(r.allow_multiple_files?'checked ':'')+disabled+'> Allow multiple files</span></label><label class="revision-field"><span><input type="checkbox" data-field="is_required" '+(r.is_required?'checked ':'')+disabled+'> Required</span></label><div class="revision-requirement-actions full">'+(readOnly?'':'<button type="button" class="btn btn-outline-secondary btn-sm" data-duplicate="requirement">Duplicate</button><button type="button" class="btn btn-outline-danger btn-sm" data-remove="requirement">Remove</button>')+'</div></article>'; }
function requirementsHtml(list,prefix){return '<div class="revision-requirements">'+(list||[]).map(function(r,i){return '<div data-requirement-index="'+i+'">'+requirementHtml(r,prefix+'-'+i)+'</div>';}).join('')+'</div>'; }
function injectRequirementControls(){if(readOnly||!root)return;root.querySelectorAll('[data-requirement]').forEach(function(node){var title=node.querySelector('[data-field="title"]')?.closest('.revision-field');if(!title||title.querySelector('[data-revision-drag-handle]'))return;var handle=document.createElement('button');handle.type='button';handle.className='revision-drag-handle';handle.draggable=true;handle.dataset.revisionDragHandle='1';handle.setAttribute('aria-label','Drag to reorder requirement');handle.title='Drag to reorder within this list';handle.innerHTML='<span class="revision-grip" aria-hidden="true"></span>';title.insertBefore(handle,title.firstChild);var actions=node.querySelector('.revision-requirement-actions');if(actions){var up=document.createElement('button');up.type='button';up.className='btn btn-outline-secondary btn-sm';up.dataset.moveRequirement='up';up.setAttribute('aria-label','Move requirement up');up.textContent='Move up';var down=document.createElement('button');down.type='button';down.className='btn btn-outline-secondary btn-sm';down.dataset.moveRequirement='down';down.setAttribute('aria-label','Move requirement down');down.textContent='Move down';actions.insertBefore(down,actions.firstChild);actions.insertBefore(up,actions.firstChild);}});}
function markRequirementWrappers(){if(!root)return;root.querySelectorAll('[data-requirement-index]').forEach(function(wrapper){wrapper.classList.add('revision-requirement-index');});}
var requirementObserver=root?new MutationObserver(function(){injectRequirementControls();markRequirementWrappers();}):null;if(requirementObserver)requirementObserver.observe(root,{childList:true,subtree:true});
function renumberDays(b){(b.days||[]).forEach(function(d,i){d.day_number=i+1;if(!d.title||/^Day \d+$/.test(d.title))d.title='Day '+(i+1);});}
function syncRequirementFields(){if(!root)return;root.querySelectorAll('[data-requirement]').forEach(function(node){var type=node.querySelector('[data-field="requirement_type"]')?.value||'checklist';node.querySelectorAll('[data-requirement-config]').forEach(function(field){field.hidden=field.dataset.requirementConfig!==type;});});}
function syncResourceBatchPicker(){var form=Array.from(document.querySelectorAll('form[enctype="multipart/form-data"]')).find(function(node){return (node.getAttribute('action')||'').includes('/admin/requests/revision-plan/save');});if(!form||!root)return;var label=form.querySelector('[data-resource-batch-picker]');if(!label){label=document.createElement('label');label.className='revision-field full';label.dataset.resourceBatchPicker='1';label.innerHTML='<span>Plan Batch <small class="revision-help">Optional shared-material grouping</small></span><select name="batch_id" class="form-select" data-resource-batch-select><option value="0">Version-wide material</option></select>';var actions=form.querySelector('.revision-actions');if(actions)form.insertBefore(label,actions);else form.appendChild(label);}var select=label.querySelector('[data-resource-batch-select]'),previous=select.value;select.innerHTML='<option value="0">Version-wide material</option>';root.querySelectorAll(':scope > [data-batch]').forEach(function(batchNode,index){var title=batchNode.querySelector(':scope > header h3')?.textContent.trim()||('Batch '+(index+1));var batchId=Number(batchIds[index]||0);var option=document.createElement('option');option.value=batchId>0?String(batchId):'0';option.textContent='Batch '+(index+1)+' · '+title;option.disabled=batchId<=0;select.appendChild(option);});if(Array.from(select.options).some(function(option){return option.value===previous&&!option.disabled;}))select.value=previous;}
function injectContentButtons(){if(readOnly||!root)return;root.querySelectorAll('[data-day]').forEach(function(dayNode){var heading=Array.from(dayNode.querySelectorAll(':scope > .revision-section-title')).find(function(node){return node.textContent.includes('Direct requirements');});if(!heading||heading.querySelector('[data-open-content]'))return;var button=document.createElement('button');button.type='button';button.className='btn btn-outline-primary btn-sm';button.dataset.openContent='1';button.dataset.batch=dayNode.closest('[data-batch]').dataset.batch;button.dataset.day=dayNode.dataset.day;button.innerHTML='<span class="fas fa-layer-group me-1" aria-hidden="true"></span>Add Content';heading.querySelector('.revision-actions')?.appendChild(button);});}
function contentTypeLabel(item){var raw=String(item.template_type||item.item_type||'resource').replace(/[_-]+/g,' ');return raw.replace(/\b\w/g,function(ch){return ch.toUpperCase();});}
function renderContentPicker(){var list=document.querySelector('[data-content-picker-list]');if(!list)return;var groups={};items.forEach(function(item){var section=String(item.section||'General content');(groups[section]||(groups[section]=[])).push(item);});list.innerHTML=Object.keys(groups).map(function(section){return '<fieldset class="revision-content-group"><legend>'+esc(section)+'</legend>'+groups[section].map(function(item){return '<label class="revision-content-option" data-content-option data-content-text="'+esc(String(item.title+' '+section+' '+contentTypeLabel(item)).toLowerCase())+'"><input type="checkbox" value="'+esc(item.id)+'"><span><strong>'+esc(item.title)+'</strong><small>'+esc(contentTypeLabel(item))+'</small></span></label>';}).join('')+'</fieldset>';}).join('') || '<div class="revision-empty">No eligible Course Content was found for this course.</div>';updateContentCount();}
function updateContentCount(){var count=document.querySelectorAll('[data-content-picker-list] input[type="checkbox"]:checked').length;var label=document.querySelector('[data-content-count]');if(label)label.textContent=count+' selected';}
var contentTarget=null;
var daysTargetBatch=0;
document.addEventListener('click',function(e){
    if(readOnly)return;
    var open=e.target.closest('[data-open-content]');
    if(open){
        contentTarget={bi:parseInt(open.dataset.batch||'0',10),di:parseInt(open.dataset.day||'0',10)};
        renderContentPicker();
        var modal=document.getElementById('revision-content-modal');
        if(window.bootstrap&&modal)bootstrap.Modal.getOrCreateInstance(modal).show();
        return;
    }
    var add=e.target.closest('[data-add-selected-content]');
    if(!add||!contentTarget)return;
    var selected=Array.from(document.querySelectorAll('[data-content-picker-list] input[type="checkbox"]:checked')).map(function(box){return String(box.value);});
    if(!selected.length)return;
    state=readState();
    var target=state.batches[contentTarget.bi]?.days[contentTarget.di];
    if(!target)return;
    var existing=target.requirements.map(function(item){return String(item.linked_course_item_id||'');});
    selected.forEach(function(id){
        if(existing.indexOf(id)>=0)return;
        var item=items.find(function(candidate){return String(candidate.id)===id;});
        if(!item)return;
        var added=req();
        added.requirement_type='course_item';
        added.linked_course_item_id=id;
        added.title=item.title;
        target.requirements.push(added);
        existing.push(id);
    });
    render();
    var modal=document.getElementById('revision-content-modal');
    if(window.bootstrap&&modal)bootstrap.Modal.getOrCreateInstance(modal).hide();
    contentTarget=null;
});
function render(){if(!root)return;(state.batches||[]).forEach(renumberDays);root.innerHTML=(state.batches||[]).map(function(b,bi){return '<article class="revision-batch" data-batch="'+bi+'"><header><div><h3>'+esc(b.title||'Batch')+'</h3></div>'+(readOnly?'':'<div class="revision-actions"><button type="button" class="btn btn-outline-secondary btn-sm" data-duplicate="batch">Duplicate</button><button type="button" class="btn btn-outline-danger btn-sm" data-remove="batch">Remove</button></div>')+'</header><div class="revision-fields"><label class="revision-field"><span>Batch title</span><input data-field="title" value="'+esc(b.title)+'" '+(readOnly?'readonly':'')+'></label><label class="revision-field"><span>Suggested duration (days)</span><input data-field="suggested_days" type="number" min="0" max="365" value="'+(b.suggested_days||0)+'" '+(readOnly?'readonly':'')+'></label><label class="revision-field full"><span>Description</span><textarea data-field="description" rows="2" '+(readOnly?'readonly':'')+'>'+esc(b.description)+'</textarea></label></div><div class="revision-section-title"><h4>Days</h4>'+(!readOnly?'<div class="revision-actions"><button type="button" class="btn btn-outline-secondary btn-sm" data-add-days>Add Days</button><button type="button" class="btn btn-outline-primary btn-sm" data-add="day">Add Day</button></div>':'')+'</div><div data-days>'+(b.days||[]).map(function(d,di){return '<article class="revision-day" data-day="'+di+'"><header><h4>Day '+(di+1)+' <span class="revision-muted">· '+esc(d.title)+'</span></h4>'+(readOnly?'':'<div class="revision-actions"><button type="button" class="btn btn-outline-secondary btn-sm" data-duplicate="day">Duplicate</button><button type="button" class="btn btn-outline-danger btn-sm" data-remove="day">Remove</button></div>')+'</header><div class="revision-fields"><label class="revision-field"><span>Day number</span><input data-field="day_number" type="hidden" value="'+(di+1)+'"><span class="revision-badge">Day '+(di+1)+'</span></label><label class="revision-field"><span>Day title</span><input data-field="title" value="'+esc(d.title)+'" '+(readOnly?'readonly':'')+'></label><label class="revision-field full"><span>Description</span><textarea data-field="description" rows="2" '+(readOnly?'readonly':'')+'>'+esc(d.description)+'</textarea></label></div><div class="revision-section-title"><h4>Direct requirements</h4>'+(!readOnly?'<div class="revision-actions"><button type="button" class="btn btn-outline-primary btn-sm" data-add="requirement">Add Requirement</button></div>':'')+'</div>'+requirementsHtml(d.requirements,'d-'+bi+'-'+di)+'<div class="revision-section-title"><h4>Activity Groups <span class="revision-muted">optional</span></h4>'+(!readOnly?'<button type="button" class="btn btn-outline-primary btn-sm" data-add="activity">Add Group</button>':'')+'</div><div data-activities>'+(d.activity_groups||[]).map(function(g,gi){return '<article class="revision-activity" data-activity="'+gi+'"><header><h5>'+esc(g.title||'Activity Group')+'</h5>'+(readOnly?'':'<button type="button" class="btn btn-outline-danger btn-sm" data-remove="activity">Remove</button>')+'</header><label class="revision-field"><span>Group title</span><input data-field="title" value="'+esc(g.title)+'" '+(readOnly?'readonly':'')+'></label><label class="revision-field mt-2"><span>Description</span><textarea data-field="description" rows="2" '+(readOnly?'readonly':'')+'>'+esc(g.description)+'</textarea></label><div class="revision-section-title"><h4>Requirements</h4>'+(!readOnly?'<button type="button" class="btn btn-outline-primary btn-sm" data-add="group-requirement">Add Requirement</button>':'')+'</div>'+requirementsHtml(g.requirements,'g-'+bi+'-'+di+'-'+gi)+'</article>';}).join('')+'</div></article>';}).join('')+'</div></article>';}).join('') || '<div class="revision-empty">Add a Batch to begin building this Version.</div>';syncRequirementFields();injectContentButtons();syncResourceBatchPicker(); }
function readField(el,field){var node=el.querySelector('[data-field="'+field+'"]');if(!node)return '';if(node.type==='checkbox')return node.checked?1:0;return node.value;}
function readRequirements(container){return Array.from(container.querySelectorAll(':scope > [data-requirement-index] > [data-requirement]')).map(function(node,i){var ids=Array.from(node.querySelector('[data-field="resource_ids"]')?.selectedOptions||[]).map(function(o){return parseInt(o.value,10)||0;});return {title:readField(node,'title'),description:readField(node,'description'),requirement_type:readField(node,'requirement_type'),is_required:readField(node,'is_required'),sort_order:i,linked_course_item_id:readField(node,'linked_course_item_id'),allow_multiple_files:readField(node,'allow_multiple_files'),accepted_file_policy:readField(node,'accepted_file_policy'),resource_ids:ids};});}
function readState(){var result={batches:[]};root.querySelectorAll(':scope > [data-batch]').forEach(function(batchNode,bi){var b={title:readField(batchNode,'title'),description:readField(batchNode,'description'),suggested_days:parseInt(readField(batchNode,'suggested_days'),10)||0,sort_order:bi,days:[]};batchNode.querySelectorAll(':scope [data-days] > [data-day]').forEach(function(dayNode,di){var d={day_number:parseInt(readField(dayNode,'day_number'),10)||di+1,title:readField(dayNode,'title'),description:readField(dayNode,'description'),sort_order:di,requirements:readRequirements(dayNode.querySelector(':scope > .revision-requirements')),activity_groups:[]};dayNode.querySelectorAll(':scope [data-activities] > [data-activity]').forEach(function(groupNode,gi){d.activity_groups.push({title:readField(groupNode,'title'),description:readField(groupNode,'description'),sort_order:gi,requirements:readRequirements(groupNode.querySelector(':scope > .revision-requirements'))});});b.days.push(d);});result.batches.push(b);});return result;}
function rerenderFromForm(){state=readState();render();}
document.addEventListener('click',function(e){var add=e.target.closest('[data-add]');if(add&&!readOnly){var holder=add.closest('[data-batch], [data-day], [data-activity]');var current=readState();var bi=parseInt(holder.closest('[data-batch]')?.dataset.batch||0,10);var di=holder.closest('[data-day]')?parseInt(holder.closest('[data-day]').dataset.day||0,10):0;var gi=holder.closest('[data-activity]')?parseInt(holder.closest('[data-activity]').dataset.activity||0,10):0;current.batches[bi]=current.batches[bi]||batch();if(add.dataset.add==='day'){current.batches[bi].days.push(day());}else if(add.dataset.add==='activity'){current.batches[bi].days[di].activity_groups.push({title:'New Activity Group',description:'',requirements:[]});}else if(add.dataset.add==='group-requirement'){current.batches[bi].days[di].activity_groups[gi].requirements.push(req());}else{current.batches[bi].days[di].requirements.push(req());}state=current;render();return;}var addBatch=e.target.closest('[data-add-batch]');if(addBatch&&!readOnly){state=readState();state.batches.push(batch());render();return;}var remove=e.target.closest('[data-remove]');if(remove&&!readOnly){state=readState();var batchNode=remove.closest('[data-batch]'),dayNode=remove.closest('[data-day]'),activityNode=remove.closest('[data-activity]');var bi=parseInt(batchNode?.dataset.batch||0,10);if(remove.dataset.remove==='batch')state.batches.splice(bi,1);else if(remove.dataset.remove==='day')state.batches[bi].days.splice(parseInt(dayNode.dataset.day||0,10),1);else if(remove.dataset.remove==='activity')state.batches[bi].days[parseInt(dayNode.dataset.day||0,10)].activity_groups.splice(parseInt(activityNode.dataset.activity||0,10),1);else {var list=activityNode?state.batches[bi].days[parseInt(dayNode.dataset.day||0,10)].activity_groups[parseInt(activityNode.dataset.activity||0,10)].requirements:state.batches[bi].days[parseInt(dayNode.dataset.day||0,10)].requirements;var reqNode=remove.closest('[data-requirement]');var reqIndex=Array.from(reqNode.parentElement.children).indexOf(reqNode);list.splice(reqIndex,1);}render();return;}if(e.target.closest('[data-publish]')){e.preventDefault();if(confirm('Finalize this Version? It will become immutable.')){var form=document.getElementById('revision-builder-form');form.querySelector('[data-structure-json]').value=JSON.stringify(readState());form.action='<?= $escape($base . '/admin/requests/revision-plan/save') ?>';form.querySelector('input[name=\"action\"]').value='publish_version';form.submit();}}});
document.addEventListener('click',function(e){
    if(readOnly)return;
    var duplicate=e.target.closest('[data-duplicate]');
    if(duplicate){
        state=readState();
        var batchNode=duplicate.closest('[data-batch]'),dayNode=duplicate.closest('[data-day]'),activityNode=duplicate.closest('[data-activity]');
        var bi=parseInt(batchNode?.dataset.batch||0,10),di=parseInt(dayNode?.dataset.day||0,10),gi=parseInt(activityNode?.dataset.activity||0,10);
        if(duplicate.dataset.duplicate==='batch'){var copiedBatch=JSON.parse(JSON.stringify(state.batches[bi]));copiedBatch.title=(copiedBatch.title||'Batch')+' (Copy)';state.batches.splice(bi+1,0,copiedBatch);}
        else if(duplicate.dataset.duplicate==='day'){var copiedDay=JSON.parse(JSON.stringify(state.batches[bi].days[di]));copiedDay.title=(copiedDay.title||'Day')+' (Copy)';state.batches[bi].days.splice(di+1,0,copiedDay);}
        else {var list=activityNode?state.batches[bi].days[di].activity_groups[gi].requirements:state.batches[bi].days[di].requirements;var reqNode=duplicate.closest('[data-requirement]'),reqWrapper=reqNode.closest('[data-requirement-index]');var ri=Array.from(reqWrapper.parentElement.children).indexOf(reqWrapper);var copiedReq=JSON.parse(JSON.stringify(list[ri]));copiedReq.title=(copiedReq.title||'Requirement')+' (Copy)';list.splice(ri+1,0,copiedReq);}
        render();return;
    }
    var addDays=e.target.closest('[data-add-days]');
    if(addDays){daysTargetBatch=parseInt(addDays.closest('[data-batch]')?.dataset.batch||0,10);var daysModal=document.getElementById('revision-add-days-modal');if(window.bootstrap&&daysModal)bootstrap.Modal.getOrCreateInstance(daysModal).show();return;}
});
document.addEventListener('click',function(e){
    if(readOnly)return;
    var remove=e.target.closest('[data-remove]');
    if(!remove)return;
    e.stopImmediatePropagation();
    state=readState();
    var batchNode=remove.closest('[data-batch]'),dayNode=remove.closest('[data-day]'),activityNode=remove.closest('[data-activity]');
    var bi=parseInt(batchNode?.dataset.batch||0,10),di=parseInt(dayNode?.dataset.day||0,10),gi=parseInt(activityNode?.dataset.activity||0,10);
    if(remove.dataset.remove==='batch')state.batches.splice(bi,1);
    else if(remove.dataset.remove==='day')state.batches[bi].days.splice(di,1);
    else if(remove.dataset.remove==='activity')state.batches[bi].days[di].activity_groups.splice(gi,1);
    else {var list=activityNode?state.batches[bi].days[di].activity_groups[gi].requirements:state.batches[bi].days[di].requirements;var wrapper=remove.closest('[data-requirement-index]');list.splice(Array.from(wrapper.parentElement.children).indexOf(wrapper),1);}
    render();
},true);
document.getElementById('revision-builder-form')?.addEventListener('submit',function(){this.querySelector('[data-structure-json]').value=JSON.stringify(readState());});
document.querySelector('[data-template-search]')?.addEventListener('input',function(){var q=this.value.toLowerCase();document.querySelectorAll('[data-template-card]').forEach(function(card){card.hidden=!!q&&!card.dataset.templateText.includes(q);});});
document.addEventListener('change',function(e){if(e.target.matches('[data-field="requirement_type"]'))syncRequirementFields();});
document.addEventListener('input',function(e){if(!e.target.matches('[data-course-item-filter]'))return;var q=e.target.value.toLowerCase().trim(),select=e.target.closest('[data-requirement-config="course_item"]').querySelector('[data-field="linked_course_item_id"]');Array.from(select.options).forEach(function(option){option.hidden=!!q&&!option.textContent.toLowerCase().includes(q);});});
document.addEventListener('input',function(e){if(!e.target.matches('[data-content-filter]'))return;var q=e.target.value.toLowerCase().trim();document.querySelectorAll('[data-content-option]').forEach(function(option){option.hidden=!!q&&!option.dataset.contentText.includes(q);});});
document.addEventListener('input',function(e){if(!e.target.matches('[data-student-filter-modal]'))return;var q=e.target.value.toLowerCase().trim();document.querySelectorAll('[data-student-row-modal]').forEach(function(row){row.hidden=!!q&&!row.dataset.studentTextModal.includes(q);});});
document.addEventListener('change',function(e){if(e.target.closest('[data-content-picker-list]'))updateContentCount();});
document.addEventListener('change',function(e){if(e.target.closest('[data-student-list-modal]')){var count=document.querySelectorAll('[data-student-list-modal] input[type="checkbox"]:checked').length,label=document.querySelector('[data-selected-modal]');if(label)label.textContent='Selected: '+count;}});
document.addEventListener('click',function(e){if(e.target.closest('[data-select-eligible-modal]')){document.querySelectorAll('[data-student-row-modal]:not([hidden]) input[type="checkbox"]').forEach(function(box){box.checked=true;});var label=document.querySelector('[data-selected-modal]');if(label)label.textContent='Selected: '+document.querySelectorAll('[data-student-list-modal] input[type="checkbox"]:checked').length;}});
document.addEventListener('click',function(e){
    var quick=e.target.closest('[data-quick-days]');
    if(quick){var custom=document.querySelector('[data-custom-days]');if(custom)custom.value=quick.dataset.quickDays;return;}
    var confirmDays=e.target.closest('[data-confirm-add-days]');
    if(confirmDays){var input=document.querySelector('[data-custom-days]'),count=parseInt(input?.value||'0',10);if(!Number.isFinite(count)||count<1)return;count=Math.min(30,count);state=readState();if(state.batches[daysTargetBatch]){for(var i=0;i<count;i++)state.batches[daysTargetBatch].days.push(day());render();}var modal=document.getElementById('revision-add-days-modal');if(window.bootstrap&&modal)bootstrap.Modal.getOrCreateInstance(modal).hide();return;}
    var publishAssign=e.target.closest('[data-publish-assign]');
    if(publishAssign){var builder=document.getElementById('revision-builder-form'),assignModal=document.getElementById('revision-publish-assign-modal');if(builder&&assignModal){assignModal.querySelector('[name="structure_json"]').value=JSON.stringify(readState());assignModal.querySelector('[name="title"]').value=builder.querySelector('[name="title"]')?.value||'';assignModal.querySelector('[name="description"]').value=builder.querySelector('[name="description"]')?.value||'';assignModal.querySelector('[name="allow_work_ahead"]').checked=!!builder.querySelector('[name="allow_work_ahead"]')?.checked;assignModal.querySelector('[data-publish-assign-summary]').textContent='Publish '+(builder.querySelector('[name="title"]')?.value||'this plan')+' and assign it to selected students.';if(window.bootstrap)bootstrap.Modal.getOrCreateInstance(assignModal).show();}return;}
});
document.querySelector('[data-student-filter]')?.addEventListener('input',function(){var q=this.value.toLowerCase().trim();document.querySelectorAll('[data-student-row]').forEach(function(row){row.hidden=!!q&&!row.dataset.studentText.includes(q);});});
document.querySelector('[data-select-eligible]')?.addEventListener('click',function(){document.querySelectorAll('[data-student-row]:not([hidden]) input[type="checkbox"]:not(:disabled)').forEach(function(box){box.checked=true;});});
document.querySelector('[data-resource-type]')?.addEventListener('change',function(){var t=this.value;document.querySelector('[data-resource-url]').classList.toggle('d-none',t!=='external_link');document.querySelector('[data-resource-file]').classList.toggle('d-none',t!=='uploaded_pdf');document.querySelector('[data-resource-item]').classList.toggle('d-none',t!=='course_item');});
var resourceType=document.querySelector('[data-resource-type]');if(resourceType)resourceType.dispatchEvent(new Event('change'));
document.querySelectorAll('[data-open-create]').forEach(function(button){button.addEventListener('click',function(){var modal=document.getElementById('revision-create-modal');if(window.bootstrap&&modal)bootstrap.Modal.getOrCreateInstance(modal).show();});});
var draggedRequirement=null;
document.addEventListener('click',function(e){if(readOnly)return;var move=e.target.closest('[data-move-requirement]');if(!move)return;var wrapper=move.closest('[data-requirement-index]'),list=wrapper?.parentElement;if(!wrapper||!list)return;var sibling=move.dataset.moveRequirement==='up'?wrapper.previousElementSibling:wrapper.nextElementSibling;if(!sibling)return;if(move.dataset.moveRequirement==='up')list.insertBefore(wrapper,sibling);else list.insertBefore(sibling,wrapper);wrapper.querySelector('[data-field="title"]')?.focus();});
document.addEventListener('dragstart',function(e){var handle=e.target.closest('[data-revision-drag-handle]');if(!handle||readOnly)return;draggedRequirement=handle.closest('[data-requirement-index]');if(!draggedRequirement)return;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','revision-requirement');draggedRequirement.classList.add('is-dragging');});
document.addEventListener('dragover',function(e){if(!draggedRequirement)return;var target=e.target.closest('[data-requirement-index]');if(!target||target===draggedRequirement||target.parentElement!==draggedRequirement.parentElement)return;e.preventDefault();e.dataTransfer.dropEffect='move';});
document.addEventListener('drop',function(e){if(!draggedRequirement)return;var target=e.target.closest('[data-requirement-index]');if(!target||target===draggedRequirement||target.parentElement!==draggedRequirement.parentElement)return;e.preventDefault();target.parentElement.insertBefore(draggedRequirement,target);draggedRequirement.querySelector('[data-field="title"]')?.focus();draggedRequirement.classList.remove('is-dragging');draggedRequirement=null;});
document.addEventListener('dragend',function(){if(draggedRequirement)draggedRequirement.classList.remove('is-dragging');draggedRequirement=null;});
render();injectRequirementControls();markRequirementWrappers();
})();
</script>
<div class="modal fade" id="revision-content-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><div><h2 class="modal-title h5 mb-1">Add course content</h2><p class="revision-help mb-0">Select one or more existing items from this course. Their original order is preserved.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input class="form-control mb-3" type="search" placeholder="Search title, section, or type" data-content-filter aria-label="Search course content"><div class="revision-content-picker" data-content-picker-list></div><p class="revision-help mt-3 mb-0" data-content-count>0 selected</p></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-primary" data-add-selected-content>Add selected content</button></div></div></div></div>
<script>
(function(){
    var modal=document.getElementById('revision-delete-modal');
    if(!modal)return;
    var idField=modal.querySelector('[data-delete-template-id]');
    var title=modal.querySelector('[data-delete-template-title]');
    var normal=modal.querySelector('[data-delete-normal-warning]');
    var activity=modal.querySelector('[data-delete-activity-warning]');
    var confirmField=modal.querySelector('[data-delete-confirmation]');
    var submit=modal.querySelector('[data-delete-submit]');
    function sync(){if(!confirmField||!submit)return;submit.disabled=!!activity&&!activity.hidden&&(confirmField.value||'').trim().toUpperCase()!=='DELETE';}
    document.addEventListener('click',function(event){
        var trigger=event.target.closest('[data-open-delete]');
        if(!trigger)return;
        if(idField)idField.value=trigger.dataset.templateId||'';
        if(title)title.textContent=trigger.dataset.templateTitle||'Revision Plan';
        var hasActivity=trigger.dataset.templateActivity==='1';
        if(activity)activity.hidden=!hasActivity;
        if(normal)normal.hidden=hasActivity;
        if(confirmField){confirmField.value='';confirmField.required=hasActivity;}
        sync();
        if(window.bootstrap)bootstrap.Modal.getOrCreateInstance(modal).show();
    });
    if(confirmField)confirmField.addEventListener('input',sync);
})();
</script>
</body></html>
